include <robotics.scad>
// TowerPro MG996R case, origin = case bottom center. Official numbers only.
B = 40.9;   // case length (X)
D = 20;     // case width (Y)
C = 37;     // case height excl. spline (Z)
E = 54;     // length across mounting tabs
F = 26.8;   // case bottom to tab underside
tab_t = 2.5; // NOT published - conservative estimate
union() {
  cuboid([B, D, C], rounding = 0.5, anchor = BOT);
  // mounting tabs, full case width, plain (hole pattern not published)
  up(F) cuboid([E, D, tab_t], rounding = 0.5, edges = "Z", anchor = BOT);
}

include <robotics.scad>
// Output spline, origin = shaft axis at case top face (z = C).
h = 42.7 - 37;  // 5.7 mm, published A - C
d = 6;          // NOT published - plain conservative cylinder
cyl(d = d, h = h, chamfer2 = 0.3, anchor = BOT, $fn = 48);
